<?php
namespace Tests\Feature;
use App\Models\{Member,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class MemberManagementTest extends TestCase {use RefreshDatabase;public function test_staff_can_create_member():void{$u=User::factory()->create(['role'=>'staff']);$response=$this->actingAs($u)->post('/members',['first_name'=>'Ada','last_name'=>'Nwosu','email'=>'ada@example.test','status'=>'active','role'=>'member','join_date'=>'2026-11-05','ministry_group_ids'=>[]]);$member=Member::where('email','ada@example.test')->firstOrFail();$response->assertRedirect(route('members.show',$member));$this->assertDatabaseHas('members',['email'=>'ada@example.test']);}public function test_only_admin_can_archive_member():void{$member=Member::create(['first_name'=>'Test','last_name'=>'Member','status'=>'active','role'=>'member']);$staff=User::factory()->create(['role'=>'staff']);$this->actingAs($staff)->delete(route('members.destroy',$member))->assertForbidden();$admin=User::factory()->create(['role'=>'admin']);$this->actingAs($admin)->delete(route('members.destroy',$member))->assertRedirect('/members');$this->assertSoftDeleted($member);}}
